/* Parity check: replay the fixtures generated by backend/scripts/gen_fixtures.py
 * through the JS ports (profit.js + pricestore.js) and diff every row against
 * the Python reference output. Exits non-zero on any mismatch.
 *
 * Usage (anywhere):  node backend/scripts/parity_check.cjs
 */
'use strict';
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..', '..');
const { evaluateAll, geTax } = require(path.join(ROOT, 'profit.js'));
const PriceStore = require(path.join(ROOT, 'pricestore.js'));

const fixtures = JSON.parse(
  fs.readFileSync(path.join(__dirname, '..', 'tests', 'fixtures.json'), 'utf-8')
);

/* ---------- deep diff ---------- */

// net_pct: Python round(x, 1) vs the JS float-scaled port can disagree by one
// rounding step on rare half-way values; cosmetic field, allow that much.
const TOLERANCE = { net_pct: 0.11 };

function diff(a, b, at, out) {
  if (a === null || b === null || a === undefined || b === undefined) {
    if (a !== b) out.push(`${at}: ${JSON.stringify(a)} != ${JSON.stringify(b)}`);
    return;
  }
  if (typeof a === 'number' && typeof b === 'number') {
    const tol = TOLERANCE[at.replace(/^\w+\./, '').split('.').pop()] ?? 0;
    if (!(Math.abs(a - b) <= tol)) out.push(`${at}: ${a} != ${b}`);
    return;
  }
  if (Array.isArray(a) || Array.isArray(b)) {
    if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length) {
      out.push(`${at}: array length/type mismatch`);
      return;
    }
    for (let i = 0; i < a.length; i++) diff(a[i], b[i], `${at}[${i}]`, out);
    return;
  }
  if (typeof a === 'object' && typeof b === 'object') {
    const keys = new Set([...Object.keys(a), ...Object.keys(b)]);
    for (const k of keys) diff(a[k], b[k], at ? `${at}.${k}` : k, out);
    return;
  }
  if (a !== b) out.push(`${at}: ${JSON.stringify(a)} != ${JSON.stringify(b)}`);
}

/* ---------- run ---------- */

const store = new PriceStore(fixtures.stale_secs, () => fixtures.now);
store.updateLatest({ data: fixtures.wiki.latest });
store.updateWindow({ data: fixtures.wiki['5m'] }, '5m');
store.updateWindow({ data: fixtures.wiki['1h'] }, '1h');

let fails = 0;

// 1. pricestore resolution parity
const sampleIds = Object.keys(fixtures.resolve_samples);
for (const iid of sampleIds) {
  const got = store.resolve(parseInt(iid, 10), fixtures.now);
  const probs = [];
  diff(got, fixtures.resolve_samples[iid], `resolve(${iid})`, probs);
  if (probs.length) {
    fails++;
    if (fails <= 10) console.log(probs.join('\n'));
  }
}
console.log(`resolve: ${sampleIds.length - fails}/${sampleIds.length} match`);

// 2. evaluate parity, both modes
for (const mode of Object.keys(fixtures.expected)) {
  const { rows } = evaluateAll(fixtures.recipes, fixtures.items, store, mode);
  const exp = fixtures.expected[mode];
  if (rows.length !== exp.length) {
    console.log(`${mode}: row count ${rows.length} != ${exp.length}`);
    fails++;
    continue;
  }
  let modeFails = 0;
  for (let i = 0; i < rows.length; i++) {
    const probs = [];
    diff(rows[i], exp[i], `${mode}[${i}].${rows[i].recipe_id}`, probs);
    if (probs.length) {
      modeFails++;
      fails++;
      if (modeFails <= 5) console.log(probs.slice(0, 8).join('\n'));
    }
  }
  console.log(`${mode}: ${rows.length - modeFails}/${rows.length} rows match`);
}

// 3. sanity: tax spot checks against the Python semantics
const taxChecks = [
  [49, 0], [50, 1], [1000, 20], [100, 2], [10_000_000_000, 5_000_000],
];
for (const [price, want] of taxChecks) {
  if (geTax(price) !== want) {
    console.log(`geTax(${price}) = ${geTax(price)}, want ${want}`);
    fails++;
  }
}
console.log('geTax spot checks done');

if (fails) {
  console.log(`FAIL: ${fails} mismatch(es)`);
  process.exit(1);
}
console.log('PASS: JS ports match the Python reference');
